# Fetch all Todoist projects and print the newest ones.
access_token = todoist_token
page_index = 0
all_projects = []
page_limit = 50
while True:
    resp = apis.todoist.show_projects(access_token=access_token, page_index=page_index, page_limit=page_limit)
    if isinstance(resp, dict) and 'message' in resp:
        print('error', resp)
        break
    if not resp:
        break
    all_projects.extend(resp)
    print('page', page_index, 'count', len(resp))
    if len(resp) < page_limit:
        break
    page_index += 1

print('total_projects', len(all_projects))

from datetime import datetime

def parse_iso(dt_str):
    if not dt_str:
        return datetime.min
    # handle trailing Z
    s = dt_str.replace('Z','+00:00')
    try:
